from collections import Counter


def transform(grid):
    """Compare aligned panels: mark equal cells, otherwise use right-panel background."""
    h, w = len(grid), len(grid[0])
    left = right = None
    if w % 2 == 1:
        c = w // 2
        if len({grid[r][c] for r in range(h)}) == 1:
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
    if left is None and h % 2 == 1:
        r = h // 2
        if len(set(grid[r])) == 1:
            left, right = grid[:r], grid[r + 1:]
    if left is None:
        raise ValueError('No centered full separator found')
    assert len(left) == len(right) and all(len(a) == len(b) for a, b in zip(left, right))
    background = Counter(v for row in right for v in row).most_common(1)[0][0]
    return [[3 if a == b else background for a, b in zip(row_a, row_b)]
            for row_a, row_b in zip(left, right)]
